Register Newborn.code:
// Register a newborn from the Lightwave eTracker and mint a Ghana Card PIN.
// The merchantKey from the credential is added for you.
registerChild({
  babyData: {
    forenames: $.data.forenames,
    surname: $.data.surname,
    gender: $.data.gender, // 'Male' | 'Female'
    dateOfBirth: $.data.dateOfBirth, // 'YYYY-MM-DD'
    timeOfbirth: $.data.timeOfBirth, // 'HH:mm' (note the API's spelling)
    placeOfBirth: $.data.facilityName,
    weightAtBirth: $.data.weightAtBirth, // all values are sent as strings, e.g. '3.2'
    noSiblingsInDelivery: '0',
    motherName: $.data.motherName,
    fatherName: $.data.fatherName,
    lightwaveETrackerID: $.data.eTrackerId,
    birthCertificateNumber: $.data.birthCertificateNumber,
    babyPicture: $.data.babyPhotoBase64,
  },
  personVouching: {
    ghanaCardPIN: $.data.voucherGhanaCardPin,
    relationToBaby: 'Mother',
    relativePhone: $.data.voucherPhone,
    etrackerLightwaveID: $.data.voucherETrackerId,
    relativePicture: $.data.voucherPhotoBase64,
  },
});

Get Minted PIN From Registration.code:
// The adaptor's get() fails before sending a request (a known adaptor bug), so
// there is no working read. Capture the minted PINs from the registration response.
registerChild({
  babyData: {
    forenames: $.data.forenames,
    surname: $.data.surname,
    gender: $.data.gender,
    dateOfBirth: $.data.dateOfBirth,
    timeOfbirth: $.data.timeOfBirth,
    placeOfBirth: $.data.facilityName,
    weightAtBirth: $.data.weightAtBirth,
    noSiblingsInDelivery: '0',
    motherName: $.data.motherName,
    fatherName: $.data.fatherName,
    lightwaveETrackerID: $.data.eTrackerId,
    birthCertificateNumber: $.data.birthCertificateNumber,
    babyPicture: $.data.babyPhotoBase64,
  },
  personVouching: {
    ghanaCardPIN: $.data.voucherGhanaCardPin,
    relationToBaby: 'Mother',
    relativePhone: $.data.voucherPhone,
    etrackerLightwaveID: $.data.voucherETrackerId,
    relativePicture: $.data.voucherPhotoBase64,
  },
});

// state.data is NIA's envelope: { data: { babyPin, voucherPin, etrackerLightwaveId }, success, code, msg }.
fn(state => {
  const { babyPin, voucherPin } = state.data.data;
  console.log(`Minted baby PIN ${babyPin} (vouched by ${voucherPin})`);
  return { ...state, babyPin };
});

Collect Minted PINs For A Batch.code:
// The adaptor's get() fails before sending a request (a known adaptor bug), so
// registrations can't be listed. Instead, keep the PINs minted in this run so they
// can be reconciled with the eTracker.
fn(state => ({ ...state, minted: [] }));

each(
  $.data.births,
  combine(
    registerChild({
      babyData: {
        forenames: $.data.forenames,
        surname: $.data.surname,
        gender: $.data.gender,
        dateOfBirth: $.data.dateOfBirth,
        timeOfbirth: $.data.timeOfBirth,
        placeOfBirth: $.data.facilityName,
        weightAtBirth: $.data.weightAtBirth,
        noSiblingsInDelivery: '0',
        motherName: $.data.motherName,
        fatherName: $.data.fatherName,
        lightwaveETrackerID: $.data.eTrackerId,
        birthCertificateNumber: $.data.birthCertificateNumber,
        babyPicture: $.data.babyPhotoBase64,
      },
      personVouching: {
        ghanaCardPIN: $.data.voucherGhanaCardPin,
        relationToBaby: 'Mother',
        relativePhone: $.data.voucherPhone,
        etrackerLightwaveID: $.data.voucherETrackerId,
        relativePicture: $.data.voucherPhotoBase64,
      },
    }),
    fn(state => {
      state.minted.push({
        eTrackerId: state.data.data.etrackerLightwaveId,
        babyPin: state.data.data.babyPin,
      });
      return state;
    })
  )
);
